/*
 * Nagad specifics. The shared behaviour (verification, races, retries, sync)
 * is covered by tests/conformance.test.ts via tests/conformance/nagad.scenario.ts.
 * All keys are throwaway pairs generated by the scenario.
 */
import * as nodeCrypto from 'node:crypto';
import { createVerify } from 'node:crypto';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { NagadCrypto, rsaPkcs1v15Decrypt } from '../../src/drivers/nagad-crypto.js';
import {
  type ChargeOptions,
  createBdPayGate,
  type GatewayConfig,
  GatewayError,
  gatewayResponse,
  NagadGateway,
  type Payment,
  PaymentStatus,
  UnsupportedOperationError,
} from '../../src/index.js';
import NagadScenario, { BASE, keys, MERCHANT_ID, seal } from '../conformance/nagad.scenario.js';
import { type MockRequest, type Routes, reply } from '../support/mock-fetch.js';
import { BASE_URL, customer, get, hit } from '../support/scenario.js';

let current: NagadScenario | undefined;

afterEach(() => {
  vi.useRealTimers();
  expect(current?.http.unmatched ?? []).toEqual([]);
  current = undefined;
});

/** Boot the simulated Nagad. Overrides take precedence over the default routes. */
function nagadScenario(
  config: GatewayConfig = {},
  overrides: Routes | ((s: NagadScenario) => Routes) = {},
): NagadScenario {
  const s = new NagadScenario();
  const baseConfig = s.config();
  const baseRoutes = s.routes.bind(s);
  s.config = () => ({ ...baseConfig, ...config });
  s.routes = () => {
    const first = typeof overrides === 'function' ? overrides(s) : overrides;

    return { ...first, ...Object.fromEntries(Object.entries(baseRoutes()).filter(([k]) => !(k in first))) };
  };
  current = s.boot();

  return s;
}

function charge(s: NagadScenario, amount: number, reference: string, extra: Partial<ChargeOptions> = {}) {
  return s.pay.gateway('nagad').charge({ amount, reference, customer: customer(), ...extra });
}

/** The latest Nagad payment, as stored. */
function nagadPayment(s: NagadScenario): Payment {
  const payment = [...s.store.payments.values()].filter((p) => p.gateway === 'nagad').at(-1);

  if (!payment) {
    throw new Error('No Nagad payment yet');
  }

  return payment;
}

async function fresh(s: NagadScenario, payment: Payment): Promise<Payment> {
  const found = await s.store.find(payment.id);

  if (!found) {
    throw new Error('payment vanished');
  }

  return found;
}

const sent = (s: NagadScenario, part: string): MockRequest[] =>
  s.http.requests.filter((r) => r.url.href.includes(part));

const bareKey = (pem: string): string => pem.replace(/-----[A-Z ]+-----|\s+/g, '');

describe('nagad', () => {
  it('initializes with an encrypted, signed payload and the KM headers, then completes', async () => {
    const s = nagadScenario({ ip: '203.0.113.10' });
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(new Date('2026-10-15T00:30:00Z'));

    const payment = await charge(s, 150, 'ORD-1', { description: 'Order 1' });

    expect(payment.gatewayPaymentId).toBe(`MDREF${payment.gatewayReference}`);
    expect(payment.checkoutUrl).toMatch(/^https:\/\/sandbox-ssl\.mynagad\.com:10061\/check-out\//);

    const [initialize] = sent(s, '/check-out/initialize/');
    expect(initialize).toBeDefined();

    if (!initialize) {
      return;
    }

    const plain = s.readSensitive(initialize);
    expect(initialize.url.href).toBe(
      `https://${BASE}/check-out/initialize/${MERCHANT_ID}/${payment.gatewayReference}?locale=EN`,
    );
    expect(initialize.method).toBe('POST');
    expect(initialize.headers.get('X-KM-Api-Version')).toBe('v-0.2.0');
    expect(initialize.headers.get('X-KM-IP-V4')).toBe('203.0.113.10');
    expect(initialize.headers.get('X-KM-Client-Type')).toBe('PC_WEB');
    expect(initialize.data.dateTime).toBe('20261015063000'); // Asia/Dhaka, UTC+6
    expect(plain.datetime).toBe('20261015063000');
    expect(plain.merchantId).toBe(MERCHANT_ID);
    expect(plain.orderId).toBe(payment.gatewayReference);
    expect(plain.challenge).toMatch(/^[0-9a-f]{40}$/);
    expect(initialize.data).not.toHaveProperty('accountNumber');

    const [complete] = sent(s, '/check-out/complete/');
    expect(complete).toBeDefined();

    if (!complete) {
      return;
    }

    const completed = s.readSensitive(complete);
    expect(complete.url.href.endsWith(`/check-out/complete/MDREF${payment.gatewayReference}`)).toBe(true);
    expect(completed).toEqual({
      merchantId: MERCHANT_ID,
      orderId: payment.gatewayReference,
      amount: '150.00',
      currencyCode: '050',
      challenge: completed.challenge,
    });
    expect(String(complete.data.merchantCallbackURL).endsWith('/bdpaygate/nagad/callback')).toBe(true);
    expect(complete.data.additionalMerchantInfo).toEqual({ reference: 'ORD-1' });
    expect(complete.headers.get('X-KM-Api-Version')).toBe('v-0.2.0');
  });

  it('echoes the challenge nagad returned when completing', async () => {
    const challenges: unknown[] = [];
    const s = nagadScenario({}, (scenario) => ({
      [`${BASE}/check-out/initialize/*`]: (request) => {
        const plain = scenario.readSensitive(request);

        return reply(
          seal({ paymentReferenceId: 'MDREF1', challenge: 'NAGADCHALLENGE', acceptDateTime: plain.datetime }),
        );
      },
      [`${BASE}/check-out/complete/*`]: (request) => {
        challenges.push(scenario.readSensitive(request).challenge);

        return reply({ callBackUrl: 'https://x', status: 'Success' });
      },
    }));

    await charge(s, 10, 'ORD-C');

    expect(challenges).toEqual(['NAGADCHALLENGE']);
  });

  it('sends a fresh 20 character alphanumeric order id per attempt', async () => {
    const s = nagadScenario();

    const first = await charge(s, 100, 'ORD-SAME');
    const second = await charge(s, 100, 'ORD-SAME');

    expect(first.gatewayReference).toMatch(/^[A-Z0-9]{20}$/);
    expect(second.gatewayReference).toMatch(/^[A-Z0-9]{20}$/);
    expect(second.gatewayReference).not.toBe(first.gatewayReference);
  });

  it('refuses an order id nagad would reject', async () => {
    const s = nagadScenario();

    class BadOrderNagad extends NagadGateway {
      protected override async createPendingPayment(options: ChargeOptions): Promise<Payment> {
        const payment = await super.createPendingPayment(options);
        payment.gatewayReference = 'BAD_ORDER_ID';

        return payment;
      }
    }

    const pay = createBdPayGate({
      baseUrl: BASE_URL,
      gateways: { nagadbad: { ...s.config(), driver: 'nagad-bad' } },
      store: s.store,
      cache: s.cache,
      fetch: s.http.fetch,
      logger: { warn() {} },
    }).extend('nagad-bad', (config, name, ctx) => new BadOrderNagad(config, name, ctx));

    await expect(
      pay.gateway('nagadbad').charge({ amount: 100, reference: 'ORD-BAD', customer: customer() }),
    ).rejects.toThrow(/must be 5 to 20 letters or digits/);
    expect(s.http.requests).toEqual([]);
  });

  it('signs with sha1 when configured', async () => {
    const s = nagadScenario({ signatureAlgorithm: 'sha1' });
    s.algorithm = 'sha1';

    const payment = await charge(s, 100, 'ORD-SHA1');

    expect(payment.checkoutUrl).toBeTruthy();
  });

  it('signs with sha256 by default, which a sha1 verifier rejects', async () => {
    const s = nagadScenario();
    s.algorithm = 'sha1';

    await expect(charge(s, 100, 'ORD-SHA')).rejects.toThrow(/signature does not verify/);
  });

  it('rejects an unknown signature algorithm', async () => {
    const s = nagadScenario({ signatureAlgorithm: 'md5' });

    await expect(charge(s, 100, 'ORD-MD5')).rejects.toThrow(
      expect.objectContaining({
        name: 'GatewayError',
        message: expect.stringContaining('Unsupported Nagad signature algorithm'),
      }),
    );
  });

  it('round-trips the RSA envelope with PEM, bare base64, escaped and file keys', async () => {
    const k = keys();
    const dir = mkdtempSync(join(tmpdir(), 'nagad'));
    const file = join(dir, 'merchant.pem');
    writeFileSync(file, k.merchantPrivate);

    try {
      const variants = [
        new NagadCrypto(k.nagadPublic, k.merchantPrivate),
        new NagadCrypto(bareKey(k.nagadPublic), bareKey(k.merchantPrivate)),
        new NagadCrypto(k.nagadPublic.replaceAll('\n', '\\n'), k.merchantPrivate.replaceAll('\n', '\\n')),
        new NagadCrypto(k.nagadPublic, file, 'SHA256withRSA'),
      ];

      for (const crypto of variants) {
        const plain = '{"merchantId":"683002007104225","orderId":"BP123"}';

        const decrypted = rsaPkcs1v15Decrypt(
          nodeCrypto,
          k.nagadPrivate,
          Buffer.from(await crypto.encrypt(plain), 'base64'),
        ).toString('utf8');
        expect(decrypted).toBe(plain);
        expect(
          createVerify('sha256')
            .update(plain)
            .verify(k.merchantPublic, Buffer.from(await crypto.sign(plain), 'base64')),
        ).toBe(true);

        const sealed = seal({ paymentReferenceId: 'MDREF1' });
        const opened = await crypto.decrypt(sealed.sensitiveData);
        expect(JSON.parse(opened)).toEqual({ paymentReferenceId: 'MDREF1' });
        expect(await crypto.verify(opened, sealed.signature)).toBe(true);
        expect(await crypto.verify(`${opened}x`, sealed.signature)).toBe(false);
      }
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  it('fails clearly on an unreadable key', async () => {
    const crypto = new NagadCrypto('not-a-key', keys().merchantPrivate);

    await expect(crypto.encrypt('x')).rejects.toThrow(GatewayError);
    await expect(crypto.encrypt('x')).rejects.toThrow(/Could not read the Nagad public key/);
  });

  it('rejects an initialize response whose signature does not verify', async () => {
    const s = nagadScenario(
      {},
      {
        [`${BASE}/check-out/initialize/*`]: () =>
          reply({
            ...seal({ paymentReferenceId: 'MDREF1', challenge: 'c' }),
            signature: Buffer.from('forged').toString('base64'),
          }),
      },
    );

    await expect(charge(s, 100, 'ORD-SIG')).rejects.toThrow(/signature does not verify/);
    expect(sent(s, '/check-out/complete/')).toEqual([]);
  });

  it('accepts an unverified response signature when verification is off', async () => {
    const s = nagadScenario(
      { verifyResponseSignature: false },
      {
        [`${BASE}/check-out/initialize/*`]: () =>
          reply({ ...seal({ paymentReferenceId: 'MDREF1', challenge: 'c' }), signature: 'garbage' }),
        [`${BASE}/check-out/complete/*`]: () => reply({ callBackUrl: 'https://x', status: 'Success' }),
      },
    );

    expect((await charge(s, 100, 'ORD-NOSIG')).checkoutUrl).toBe('https://x');
  });

  it('surfaces nagad error envelopes', async () => {
    const s = nagadScenario(
      {},
      {
        [`${BASE}/check-out/initialize/*`]: () =>
          reply({ reason: '16_0006_076', message: 'Transaction Date Time Not in allowed window' }, 400),
      },
    );

    await expect(charge(s, 100, 'ORD-ERR')).rejects.toThrow(
      'Transaction Date Time Not in allowed window [16_0006_076]',
    );
    expect(gatewayResponse(nagadPayment(s), 'initialize')).toMatchObject({ reason: '16_0006_076' });
  });

  it('keeps the paymentRefId when the complete call fails, so sync can settle it', async () => {
    const s = nagadScenario(
      {},
      {
        [`${BASE}/check-out/complete/*`]: () =>
          reply({ reason: '16_0006_059', message: 'Invalid Sensitive Data' }, 400),
      },
    );

    await expect(charge(s, 100, 'ORD-LOST')).rejects.toThrow(GatewayError);

    const payment = nagadPayment(s);
    expect(payment.gatewayPaymentId).toBe(`MDREF${payment.gatewayReference}`);
    expect((await s.pay.sync(payment)).status).toBe(PaymentStatus.Completed);
  });

  it('verifies with the stored paymentRefId, not the one in the callback', async () => {
    const s = nagadScenario();
    const payment = await charge(s, 100, 'ORD-REF');

    const response = await hit(
      s.pay,
      get('/bdpaygate/nagad/callback', {
        order_id: payment.gatewayReference,
        payment_ref_id: 'SOMEONE-ELSES-PAID-REF',
        status: 'Success',
      }),
    );

    expect(response.headers.get('location')).toBe(`/paid?payment=${payment.id}`);
    expect(
      s.http.requests.some(
        (r) => r.url.href.endsWith(`/verify/payment/${payment.gatewayPaymentId}`) && r.method === 'GET',
      ),
    ).toBe(true);
    expect(sent(s, 'SOMEONE-ELSES')).toEqual([]);

    const after = await fresh(s, payment);
    expect(after.status).toBe(PaymentStatus.Completed);
    expect(after.gatewayTransactionId).toBe(`ISS${payment.gatewayReference.slice(2, 10)}`);
  });

  it('sends the forwarded customer ip when verifying a callback', async () => {
    const s = nagadScenario({ ip: '203.0.113.10' });
    const payment = await charge(s, 100, 'ORD-FWD');

    await s.pay.fetch(
      new Request(`${BASE_URL}/bdpaygate/nagad/callback?order_id=${payment.gatewayReference}`, {
        headers: { 'x-forwarded-for': '198.51.100.9, 10.0.0.1' },
      }),
    );

    const [verify] = sent(s, '/verify/payment/');
    expect(verify?.headers.get('X-KM-IP-V4')).toBe('198.51.100.9');
  });

  it('does not complete when verify returns another order', async () => {
    const s = nagadScenario({}, (scenario) => ({
      [`${BASE}/verify/payment/*`]: () =>
        reply({ ...scenario.verifyBody(nagadPayment(scenario), 'Success'), orderId: 'BPOTHERORDER00000000' }),
    }));
    const payment = await charge(s, 100, 'ORD-OTHER');

    const response = await hit(
      s.pay,
      get('/bdpaygate/nagad/callback', { order_id: payment.gatewayReference }),
    );

    expect(response.headers.get('location')).toBe('/failed');
    expect((await fresh(s, payment)).status).toBe(PaymentStatus.Pending);
  });

  it.each(['130', '130.0', '130.00'])(
    'compares amounts numerically, whatever decimals nagad sends (%s)',
    async (reported) => {
      const s = nagadScenario({}, (scenario) => ({
        [`${BASE}/verify/payment/*`]: () =>
          reply({ ...scenario.verifyBody(nagadPayment(scenario), 'Success'), amount: reported }),
      }));
      const payment = await charge(s, 130, 'ORD-AMT');

      await hit(s.pay, get('/bdpaygate/nagad/callback', { order_id: payment.gatewayReference }));

      expect((await fresh(s, payment)).status).toBe(PaymentStatus.Completed);
    },
  );

  it('stays pending when verify does not know the payment yet', async () => {
    const s = nagadScenario(
      {},
      {
        [`${BASE}/verify/payment/*`]: () =>
          reply({ reason: '16_0004_999', message: 'Please verify provided data and try again' }, 404),
      },
    );
    const payment = await charge(s, 100, 'ORD-404');

    expect((await s.pay.sync(payment)).status).toBe(PaymentStatus.Pending);
    expect(gatewayResponse(await fresh(s, payment), 'sync')).toMatchObject({
      reason: '16_0004_999',
      http_status: 404,
    });
  });

  it.each([
    ['Cancelled', PaymentStatus.Cancelled],
    ['Aborted', PaymentStatus.Cancelled],
    ['Failed', PaymentStatus.Failed],
    ['Fraud', PaymentStatus.Failed],
    ['UnKnownFailed', PaymentStatus.Failed],
    ['InProgress', PaymentStatus.Pending],
    ['PinGiven', PaymentStatus.Pending],
    ['SomethingNew', PaymentStatus.Pending],
  ])('maps verified status %s to %s', async (status, expected) => {
    const s = nagadScenario({}, (scenario) => ({
      [`${BASE}/verify/payment/*`]: () => reply(scenario.verifyBody(nagadPayment(scenario), status)),
    }));
    const payment = await charge(s, 100, 'ORD-MAP');

    expect((await s.pay.sync(payment)).status).toBe(expected);
  });

  it('uses a public customer ip, and the configured ip otherwise', async () => {
    const s = nagadScenario({ ip: '203.0.113.10' });

    await charge(s, 100, 'ORD-IP1', { meta: { customerIp: '198.51.100.7' } });
    await charge(s, 100, 'ORD-IP2', { meta: { customerIp: '192.168.1.5' } });

    const ips = sent(s, 'initialize').map((r) => r.headers.get('X-KM-IP-V4'));
    expect(ips).toEqual(['198.51.100.7', '203.0.113.10']);
  });

  it('honours baseUrl, merchantNumber, locale and client type', async () => {
    const s = nagadScenario(
      {
        baseUrl: 'http://sandbox.mynagad.com:30001/api/dfs/',
        merchantNumber: '01700000000',
        locale: 'bn',
        clientType: 'MOBILE_WEB',
      },
      {
        'sandbox.mynagad.com:30001/api/dfs/check-out/initialize/*': () =>
          reply(seal({ paymentReferenceId: 'MDREF9', challenge: 'c' })),
        'sandbox.mynagad.com:30001/api/dfs/check-out/complete/*': () =>
          reply({ callBackUrl: 'https://x', status: 'Success' }),
      },
    );

    await charge(s, 100, 'ORD-BASE');

    expect(
      s.http.requests.some(
        (r) =>
          r.url.href.startsWith('http://sandbox.mynagad.com:30001/api/dfs/check-out/initialize/') &&
          r.url.href.endsWith('?locale=BN') &&
          r.data.accountNumber === '01700000000' &&
          r.headers.get('X-KM-Client-Type') === 'MOBILE_WEB',
      ),
    ).toBe(true);
  });

  it('has no refund API', async () => {
    const s = nagadScenario();
    const payment = await charge(s, 100, 'ORD-RF');

    expect(s.pay.gateway('nagad').capabilities.refunds).toBe(false);
    await expect(s.pay.refund(payment)).rejects.toThrow(UnsupportedOperationError);
  });

  it('refuses non-BDT charges', async () => {
    const s = nagadScenario();
    const pay = createBdPayGate({
      baseUrl: BASE_URL,
      gateways: { nagad: s.config() },
      store: s.store,
      cache: s.cache,
      fetch: s.http.fetch,
      logger: { warn() {} },
      currency: 'USD',
    });

    await expect(
      pay.gateway('nagad').charge({ amount: 100, reference: 'ORD-USD', customer: customer() }),
    ).rejects.toThrow(/only accepts BDT/);
  });
});

describe('RSA PKCS#1 v1.5 decryption on Node 20', () => {
  // Node 20 refuses PKCS#1 v1.5 private decryption (CVE-2023-46809); simulate it on any Node.
  const node20 = {
    ...nodeCrypto,
    privateDecrypt: ((key: Parameters<typeof nodeCrypto.privateDecrypt>[0], data: NodeJS.ArrayBufferView) => {
      if (
        typeof key === 'object' &&
        'padding' in key &&
        key.padding === nodeCrypto.constants.RSA_PKCS1_PADDING
      ) {
        throw new TypeError(
          'RSA_PKCS1_PADDING is no longer supported for private decryption, this can be reverted with --security-revert=CVE-2023-46809',
        );
      }

      return nodeCrypto.privateDecrypt(key, data);
    }) as typeof nodeCrypto.privateDecrypt,
  } as typeof nodeCrypto;

  const { publicKey, privateKey } = nodeCrypto.generateKeyPairSync('rsa', { modulusLength: 2048 });

  it('removes the padding itself and returns the plaintext', () => {
    for (const plain of ['{"status":"Success"}', 'x', 'ব'.repeat(60)]) {
      const encrypted = nodeCrypto.publicEncrypt(
        { key: publicKey, padding: nodeCrypto.constants.RSA_PKCS1_PADDING },
        Buffer.from(plain),
      );

      expect(rsaPkcs1v15Decrypt(node20, privateKey, encrypted).toString('utf8')).toBe(plain);
    }
  });

  it('rejects data that is not PKCS#1 v1.5 padded', () => {
    const raw = Buffer.alloc(256, 7);
    raw[0] = 0;
    const encrypted = nodeCrypto.publicEncrypt(
      { key: publicKey, padding: nodeCrypto.constants.RSA_NO_PADDING },
      raw,
    );

    expect(() => rsaPkcs1v15Decrypt(node20, privateKey, encrypted)).toThrow('RSA decryption failed.');
  });
});
